# Let me try shifting the left side
# Shift left by k: output shows left shifted by k column positions
# Shift right by k: output shows left shifted left by k

def shift_left_by(left, k):
    result = [0, 0, 0, 0]
    for j in range(4):
        src = (j - k) % 4
        result[j] = left[src]
    return result

def shift_right_by(left, k):
    result = [0, 0, 0, 0]
    for j in range(4):
        src = (j + k) % 4
        result[j] = left[src]
    return result

